class PushMigrationStatement extends PDOStatement{public function __construct(){}public function fetchAll(int $mode=PDO::FETCH_DEFAULT,mixed ...$args):array{return range(1,43);}}
class PushMigrationProbe extends PDO{public array $statements=[];public function __construct(){}public function getAttribute(int $attribute):mixed{return 'pgsql';}public function beginTransaction():bool{return true;}public function commit():bool{return true;}public function query(string $query,?int $fetchMode=null,mixed ...$fetchModeArgs):PDOStatement|false{return new PushMigrationStatement;}public function exec(string $statement):int|false{if(str_starts_with($statement,'CREATE TABLE push_')||str_starts_with($statement,'CREATE INDEX push_'))$this->statements[]=$statement;return 0;}}
